#!/usr/bin/env python3
"""Gathers the score files behind every number of the report and the talk into scores/<topic>/ and writes SCORES.md with the headline numbers
(read from the files, not typed).  Also computes the memory odds ratios per language (they were only an ad-hoc check before).
Run with the Python that has pandas, numpy, statsmodels (regenerate.sh does)."""
import glob, json, os, shutil, sys
import numpy as np, pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__)); FR = os.path.dirname(HERE); PR = os.path.dirname(FR); SC = os.path.join(FR, "scores")
TOPICS = {
    "level1_classification": ["ml_model/results/*.csv", "ml_model/results/*.txt", "new_presentation/previous_talk_graphs/results/level1/*.csv"],
    "level2_ranking_9_repos": ["presentation/data/*.csv", "presentation/data/*.json", "interest_exp/results/*.txt", "interest_exp/results/*summary*.csv"],
    "real_33_repositories": ["real_project_analysis/results/a3*.csv", "real_project_analysis/results/a3*.json", "real_project_analysis/results/a3*.txt", "real_project_analysis/results/a4*.csv",
                             "real_project_analysis/results/a4*.json", "real_project_analysis/results/a4*.txt", "real_project_analysis/INSIGHTS_REAL_PROJECTS.txt", "real_project_analysis/DATASET_DESIGN_SPEC.md"],
    "natural_pairs": ["real_project_analysis/results/b1_label_check.csv", "real_project_analysis/results/b3_*.csv", "real_project_analysis/results/b3_report.txt"],
    "synthetic_v1": ["insights/synthetic/results/*.csv", "insights/synthetic/INSIGHTS_SYNTHETIC.md"],
    "synthetic_v2": ["synthetic_dataset_v2/acceptance_v1.csv", "synthetic_dataset_v2/acceptance_v2.csv", "synthetic_dataset_v2/acceptance_v2*.txt", "synthetic_dataset_v2/acceptance_v1.txt", "synthetic_dataset_v2/results/*.csv",
                     "synthetic_dataset_v2/results/*.txt", "synthetic_dataset_v2/compile_check.txt", "synthetic_dataset_v2/results_level2/*.csv", "synthetic_dataset_v2/README.md"],
    "earlier_insights_and_new_experiments": ["insights/results/*.csv", "insights/new/results/*.csv", "insights/new/results/*.txt", "insights/INSIGHTS.md"],
    "scenarios": ["scenario_analysis/results/*.csv", "scenario_analysis/results/*.json", "scenario_analysis/results/*.txt"],
    "code_insights": ["code_insights/results/c2_traits.csv", "code_insights/results/c4_rates.json", "code_insights/results/k2_tests.csv", "code_insights/examples/*.json", "code_insights/examples/*.txt"],
    "embedding_comparison_unfinished": ["embedding_generalisation/results/*.csv"],
}
n = 0
for t, pats in TOPICS.items():
    os.makedirs(os.path.join(SC, t), exist_ok=True)
    for pat in pats:
        for f in glob.glob(os.path.join(PR, pat)):
            if os.path.isfile(f) and os.path.getsize(f) < 3_000_000: shutil.copy2(f, os.path.join(SC, t, os.path.basename(f))); n += 1
print("copied", n, "score files")

L = []
w = lambda s="": L.append(s)
rd = lambda p: pd.read_csv(os.path.join(PR, p))
w("# Headline numbers (read from the files of this repository, regenerated by reproduce/tools/collect_scores.py)\n")

# ---- level 1
s = rd("ml_model/results/summary.csv"); s = s[(s.layout == "delta_only") & (s.model == "kbest10_random_forest")]
w("## Level 1: debt type, 10-best features + random forest (ml_model/results/summary.csv)\n\n| protocol | without time | with time |\n|---|---|---|")
for p in ("given_stratified", "repeated_stratified", "given_by_project", "leave_one_project_out"):
    a = s[(s.protocol == p) & (~s.with_time)].accuracy_mean.iloc[0]; b = s[(s.protocol == p) & (s.with_time)].accuracy_mean.iloc[0]; w(f"| {p} | {a:.3f} | {b:.3f} |")
w("\nMajority class share: 0.426.\n")
# ---- level 2, 9 repos
d = rd("presentation/data/prioritization_summary.csv"); d = d[d.protocol == "leave-one-repo-out"]
w("## Level 2: capture of next-release interest, 9 repositories, leave-one-repo-out (presentation/data/prioritization_summary.csv)\n\n| model | top 10% | top 20% | top 30% | lift@20 | NDCG@20 |\n|---|---|---|---|---|---|")
for _, r in d.iterrows(): w(f"| {r.model} | {100*r.cap10:.1f} | {100*r.cap20:.1f} | {100*r.cap30:.1f} | {r.lift20:.2f} | {r.ndcg20:.3f} |")
w("\n(random = 10 / 20 / 30 by definition)\n")
# ---- 33 repos
g = rd("real_project_analysis/results/a3_group_caps.csv"); g = g[g.protocol == "LORO"]; m = g.groupby(["model", "top"]).cap.mean() * 100
w("## Ranking on 33 repositories, leave-one-repo-out, 427 groups (real_project_analysis/results/a3_group_caps.csv)\n\n| rule | top 20% | top 30% | top 50% |\n|---|---|---|---|\n| random | 20.0 | 30.0 | 50.0 |")
for k, nm in (("size", "size only"), ("persist", "persistence"), ("persist_size", "persistence, size as tie-break"), ("logit_base", "size + history (logistic)"), ("gb_base", "size + history (boosting)")): w(f"| {nm} | {m[(k,20)]:.1f} | {m[(k,30)]:.1f} | {m[(k,50)]:.1f} |")
w("\nPaired differences with intervals (e.g. size + history minus persistence with size ties: +2.3 [-0.1, 4.6] at 20%, +3.0 [0.8, 5.2] at 30%) are in real_project_analysis/results/a3_report.txt.")
w("Note: the difference to PLAIN persistence is 41.5 - 39.8 = 1.7 points at 20% and 53.2 - 51.0 = 2.2 at 30%.\n")
for ln in open(os.path.join(PR, "real_project_analysis/results/a3_report.txt"), errors="ignore"):
    if "AUC" in ln and "0.7" in ln: w("    " + ln.strip()[:160])
# ---- corpus
N = json.load(open(os.path.join(PR, "real_project_analysis/results/a3_numbers.json")))
w("\n## Corpus (a3_numbers.json)\n\n" + ", ".join(f"{k} = {v}" for k, v in N.items() if isinstance(v, (int, float)))[:600] + "\n")
# ---- insights
dose = rd("real_project_analysis/results/a3_memory_dose.csv"); w("## Insight 1: share paying by number of earlier events (a3_memory_dose.csv)\n\n" + ", ".join(f"{r.past_bin}: {100*r['mean']:.1f}%" for _, r in dose.iterrows()) + "\n")
rc = rd("real_project_analysis/results/a3_release_clock.csv"); gg = rc.groupby("step").agg(n=("ev", "size"), rate=("rate", "mean"))
w("## Insight 3: share of instances paying, by release type (a3_release_clock.csv)\n\n" + ", ".join(f"{k}: {100*v.rate:.1f}% (n={int(v.n)})" for k, v in gg.iterrows()))
B = json.load(open(os.path.join(PR, "real_project_analysis/results/a3b_numbers.json"))); w(f"\nR2 of the release interest: {B['clock_r2']}\nMatched enrichment: {B['enr_matched']}\n")
# ---- memory odds ratio per language (statsmodels)
try:
    import statsmodels.formula.api as smf
    sys.path.insert(0, os.path.join(PR, "scenario_analysis", "code")); sys.argv = ["x"]
    import s1_scenarios as S
    T, _ = S.build(S.REAL, "real"); T["ls"] = np.log(T.nloc0); out = []
    for lang in ("python", "c"):
        x = T[T.lang == lang]; mod = smf.logit("event ~ prev_event + ls + C(repo)", x).fit(disp=0, cov_type="cluster", cov_kwds={"groups": x.repo.astype("category").cat.codes})
        ci = np.exp(mod.conf_int().loc["prev_event"]); out.append(dict(language=lang, odds_ratio=round(float(np.exp(mod.params["prev_event"])), 2), lo=round(float(ci[0]), 2), hi=round(float(ci[1]), 2), rows=len(x)))
    O = pd.DataFrame(out); O.to_csv(os.path.join(SC, "real_33_repositories", "memory_odds_ratio_by_language.csv"), index=False)
    w("## Memory: odds ratio of an event after an event in the previous release pair, size and repository controlled (memory_odds_ratio_by_language.csv)\n\n" + O.to_string(index=False) + "\n")
except Exception as e:
    w(f"(memory odds ratio per language not computed here: {e})\n")
# ---- scenarios
sc = rd("scenario_analysis/results/s1_scenarios.csv"); w("## Scenarios (scenario_analysis/results/s1_scenarios.csv)\n\nVerdicts: " + str(sc.verdict.value_counts().to_dict()) + "\n")
sm = rd("scenario_analysis/results/s2_summary.csv") if os.path.exists(os.path.join(PR, "scenario_analysis/results/s2_summary.csv")) else None
if sm is not None: w("Rule discovery (s2_summary.csv):\n\n" + sm.to_string(index=False) + "\n")
# ---- code insights
c2 = rd("code_insights/results/c2_traits.csv"); w("## Code traits (c2_traits.csv): rate ratio at equal size\n\n" + c2[["trait", "c_rr", "c_lo", "c_hi", "python_rr", "python_lo", "python_hi"]].round(2).to_string(index=False) + "\n")
k2 = rd("code_insights/results/k2_tests.csv"); w("## Clones (k2_tests.csv)\n\n" + k2[["test", "lang", "rr", "lo", "hi", "n_repos", "p_partner", "p_control"]].to_string(index=False) + "\n")
# ---- synthetic v2
a2 = rd("synthetic_dataset_v2/acceptance_v2.csv"); a1 = rd("synthetic_dataset_v2/acceptance_v1.csv")
pc = [c for c in a2.columns if "pass" in c.lower() or "ok" in c.lower()]
w("## Synthetic benchmark v2 acceptance panel (acceptance_v1.csv, acceptance_v2.csv)\n\ncolumns: " + ", ".join(a2.columns) + (f"\n\nv1 passed: {int(a1[pc[0]].sum())} of {len(a1)}; v2 passed: {int(a2[pc[0]].sum())} of {len(a2)}\n" if pc else "\n"))
open(os.path.join(FR, "SCORES.md"), "w").write("\n".join(L)); print("SCORES.md written")
